/* Playable world shell, persistent RPG menus and keyboard / touch movement. */
(() => {
'use strict';const G=window.RPG,DB=G.DB,C=DB.config,T=DB.ui,A=window.RPGAudio,$=id=>document.getElementById(id),find=(a,id)=>a.find(x=>x.id===id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),copy=v=>JSON.parse(JSON.stringify(v));
let scene='title',modalKind=null,renderer=null,lastFrame=0,hudClock=0,saveClock=0,selectedRace=DB.races[0].id,selectedClass=DB.classes[0].id,characterName='',selectedItem=null,bagFilter='all',talentTab='tree',skillSlot=0,smithTab='enhance',currentNpc=null,entryPortal=null,mapFocus=null,shopFilter='consumable',worldInteraction=null,toastTimer,joystickPointer=null;
let journalTab='quests',questFilter='all',questPage=0,regionFilter=null,expeditionRule=DB.expeditionRules[0].id;
const keys=new Set(),stick={x:0,y:0};let preferences={music:DB.audio.music,effects:DB.audio.effects,musicVolume:C.musicVolume,effectVolume:C.effectVolume};try{preferences={...preferences,...JSON.parse(localStorage.getItem(C.prefsKey)||'{}')};}catch{}
for(const [key,value]of Object.entries(DB.theme.colors))document.documentElement.style.setProperty('--'+key,value);for(const [key,value]of Object.entries(DB.theme.fonts))document.documentElement.style.setProperty('--font-'+key,value);document.title=DB.meta.title+' · '+DB.meta.subtitle;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',DB.theme.colors.bg);A.applyPreferences(preferences);
function icon(id){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${DB.theme.icons[id]||DB.theme.icons.signature}</svg>`;}
function button(action,label,data={},cls='',disabled=false){return `<button data-action="${action}" ${Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')} class="${cls}" ${cls.includes('icon-button')?`aria-label="${esc(T[action]||action)}"`: ''} ${disabled?'disabled':''}>${label}</button>`;}
function tag(label,cls=''){return `<span class="tag ${cls}">${esc(label)}</span>`;}
function num(v){return Number(Number(v).toFixed(C.decimalDigits));}
function statValue(key,value){if(DB.percentStats.includes(key))return num(value*C.percentage)+'%';if(DB.multiplierStats.includes(key))return num(value)+'×';return String(num(value));}
function changeValue(ch){const value=ch.op==='multiply'?(ch.value-1)*C.percentage:ch.value*(DB.percentStats.includes(ch.stat)?C.percentage:1);return (value>0?'+':'')+num(value)+(ch.op==='multiply'||DB.percentStats.includes(ch.stat)?'%':'');}
function changes(list){return `<ul class="effect-list">${list.map(ch=>{const delta=(ch.op==='multiply'?ch.value-1:ch.value)*(DB.statDirections[ch.stat]||1);return `<li class="${delta>=0?'positive':'negative'}"><span>${esc(DB.statLabels[ch.stat])}</span><strong>${esc(changeValue(ch))}</strong></li>`;}).join('')}</ul>`;}
function toast(value,bad=false){if(!value)return;clearTimeout(toastTimer);$('toast').textContent=value;$('toast').className='toast visible'+(bad?' bad':'');toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),C.noticeTime*C.milliseconds);}
function result(r,refresh=false){if(!r?.ok){toast(r?.message||T.locked,true);return false;}if(r.message)toast(r.message);save();if(refresh)refreshModal();updateHUD();return true;}
function save(){if(!G.state()||window.RPGOnline?.isActive())return;try{localStorage.setItem(C.storageKey,JSON.stringify(G.snapshot()));}catch{}}
function clearInput(){keys.clear();stick.x=0;stick.y=0;joystickPointer=null;G.setInput(0,0);const knob=$('joystick-knob');if(knob)knob.style.transform='translate(0,0)';}
function openModal(kind,title,body,wide=false){modalKind=kind;clearInput();$('modal').className='modal '+(wide?'wide':'')+' modal-'+kind;$('modal').innerHTML=`<div class="modal-heading"><div><small>${esc(DB.meta.title)} · ${esc(window.RPGOnline?.isActive()?T.onlineLive:T.paused)}</small><h2 id="modal-title">${esc(title)}</h2></div>${button('close',icon('close'),{},'icon-button close-button')}</div><div id="modal-scroll" class="modal-scroll">${body}</div>`;$('modal-backdrop').hidden=false;requestAnimationFrame(()=>$('modal').querySelector('button:not(:disabled),input')?.focus());}
function closeModal(){modalKind=null;$('modal-backdrop').hidden=true;clearInput();$('world')?.focus({preventScroll:true});}
function showTitle(){scene='title';renderer=null;closeModal();const s=G.state();$('app').innerHTML=`<main class="title-page"><div class="title-landscape"><div class="title-sun"></div><div class="title-hills"></div><div class="title-castle">${icon('home')}</div></div><section class="title-card"><span class="eyebrow">${esc(T.titleTag)}</span><div class="brand-seal">${icon('brand')}</div><h1>${esc(DB.meta.title)}</h1><h2>${esc(DB.meta.subtitle)}</h2><p>${esc(DB.world.body)}</p><div class="title-actions">${button('online-open',`${icon('online')}${esc(T.online)}`,{},'primary online-start')}${s?button('continue',`${icon('resume')}<span>${esc(T.continue)}<small>${esc(s.name)} · ${esc(T.level)}${s.level} · ${esc(DB.maps[s.mapId].name)}</small></span>`,{},'primary'):''}${button('new',`${icon('plus')}${esc(T.newGame)}`,{},s?'':'primary')}${button('settings',`${icon('settings')}${esc(T.settings)}`)}</div><small class="title-control">${esc(T.autoCombat)}</small></section></main>`;}
function showCreation(){scene='create';closeModal();const race=find(DB.races,selectedRace),ch=find(DB.classes,selectedClass),st=G.previewCharacter(race.id,ch.id);$('app').innerHTML=`<main class="creation-page"><header class="creation-heading"><div><span class="eyebrow">${esc(DB.meta.title)} · ${esc(T.newAdventure)}</span><h1>${esc(T.createTitle)}</h1><p>${esc(T.createHint)}</p></div>${button('title',`${icon('home')}${T.back}`)}</header><div class="creation-layout"><section class="create-options parchment"><h2>${esc(T.selectRace)}</h2><div class="race-grid">${DB.races.map(r=>button('race',`<span>${window.RPGArt.heroPortrait(r.id,selectedClass)}</span><strong>${esc(r.name)}</strong><small>${esc(r.tag)}</small>`,{id:r.id},r.id===selectedRace?'selected':'')).join('')}</div><h2>${esc(T.selectClass)}</h2><div class="class-grid">${DB.classes.map(c=>button('class',`${icon(c.icon)}<span><strong>${esc(c.name)}</strong><small>${esc(c.role)}</small></span>`,{id:c.id},c.id===selectedClass?'selected':'')).join('')}</div></section><aside class="character-preview parchment"><div class="character-portrait">${window.RPGArt.heroPortrait(race.id,ch.id,C.titlePreviewScale)}</div><span class="eyebrow">${esc(race.name)} · ${esc(ch.name)}</span><h2>${esc(ch.name)}</h2><p>${esc(ch.description)}</p><div class="base-stats">${['hp','mp','attack','spell','speed','defense'].map(key=>`<span>${esc(DB.statLabels[key])}<strong>${esc(statValue(key,st[key]))}</strong></span>`).join('')}</div><div class="race-trait"><strong>${esc(race.name)}</strong><p>${esc(race.description)}</p>${changes(race.stats)}</div><label class="name-input">${esc(T.name)}<input id="character-name" maxlength="${C.nameLength}" value="${esc(characterName)}" placeholder="${esc(T.namePlaceholder)}"></label>${button('start',`${icon('fight')}${esc(T.start)}`,{},'primary full')}<small>${esc(T.autoCombat)}</small></aside></div></main>`;}
function startGame(){if(!result(G.create(selectedRace,selectedClass,characterName)))return;save();showGame();toast(T.characterCreated);}
function showGame(){scene='game';closeModal();const s=G.state(),ch=find(DB.classes,s.classId);$('app').innerHTML=`<div class="game-layout"><header class="game-header"><div class="hero-header"><span class="hero-mini">${window.RPGArt.heroPortrait(s.raceId,s.classId)}</span><div><strong>${esc(s.name)} <b id="hero-level"></b></strong><small>${esc(find(DB.races,s.raceId).name)} · ${esc(ch.name)}</small></div></div><div class="vitals"><div class="vital hp"><span>${esc(T.hp)}</span><div class="meter"><i id="hp-fill"></i></div><b id="hp-number"></b></div><div class="vital mp"><span>${esc(T.mp)}</span><div class="meter"><i id="mp-fill"></i></div><b id="mp-number"></b></div><div class="xp-meter"><i id="xp-fill"></i></div><div id="blessing-indicator" class="blessing-indicator" hidden>${icon('heart')}<span id="blessing-name"></span><b id="blessing-time"></b></div></div><div class="location-header"><strong id="map-name"></strong><small id="map-status"></small></div><div class="header-buttons">${button('online-open',icon('online'),{},'icon-button')}${button('help',icon('quest'),{},'icon-button')}${button('fullscreen',icon('fullscreen'),{},'icon-button')}${button('settings',icon('settings'),{},'icon-button')}</div></header><main id="play-stage" class="play-stage"><canvas id="world" tabindex="0" aria-label="${esc(T.controls)}"></canvas><button class="quest-tracker" data-action="quests"><small>${icon('quest')}<span id="quest-type"></span></small><strong id="quest-title"></strong><span id="quest-line"></span><em id="quest-route"></em></button><button class="minimap" data-action="map" aria-label="${esc(T.map)}"><canvas id="minimap"></canvas><span>${icon('map')}<b id="mini-name"></b></span></button><div id="boss-hud" class="boss-hud" hidden><div><strong id="boss-name"></strong><small id="boss-health"></small></div><div class="meter"><i id="boss-fill"></i></div></div><div id="map-objective" class="map-objective" hidden></div><div id="loot-feed" class="loot-feed"></div><button id="online-status" class="online-status" data-action="online-open">${esc(T.online)}</button><div id="online-party-hud" class="online-party-hud" hidden></div><div id="world-notices" class="world-notices" role="status"></div><div id="joystick" class="joystick" aria-label="${esc(T.mobileControls)}"><span></span><b id="joystick-knob"></b></div><div class="quick-actions">${dashButton()}${button('potion',`${icon('potion')}<strong id="potion-count"></strong><small>${esc(keyLabel('potion'))}</small><i id="potion-cooldown"></i>`,{},'potion-button')}${button('interact',`<span class="interact-key">${esc(keyLabel('interact'))}</span><span><strong id="interaction-name"></strong><small id="interaction-action"></small></span>`,{},'interact-button')}</div></main><footer class="game-footer"><nav>${[['inventory','bag',T.bag],['talents','training',T.talents],['quests','quest',T.quests],['map','map',T.map]].map(([action,id,label])=>button(action,`${icon(id)}<span>${esc(label)}</span>${action==='talents'?'<b id="point-count"></b>':''}`,{},'footer-button')).join('')}</nav><div id="auto-skills" class="auto-skills"></div><div class="footer-wallet">${icon('coins')}<strong id="gold-count"></strong></div></footer></div>`;renderer=new window.RPGRenderer($('world'),$('minimap'));bindJoystick();updateHUD();renderer.render(1);save();}
function updateHUD(){if(scene!=='game'||!$('world'))return;const s=G.state(),p=s.player,st=G.stats(),map=G.mapDef();$('play-stage').dataset.kind=map.kind;$('hero-level').textContent=T.level+s.level;for(const key of ['hp','mp']){$(key+'-fill').style.width=Math.max(0,p[key]/st[key]*C.percentage)+'%';$(key+'-number').textContent=Math.ceil(p[key])+' / '+st[key];}$('xp-fill').style.width=(s.level>=C.maxLevel?C.percentage:s.xp/G.xpNeeded()*C.percentage)+'%';$('map-name').textContent=map.name;$('mini-name').textContent=map.name+' · '+G.worldPhase().label;$('map-status').title=T.nightHint;$('map-status').textContent=DB.mapKinds[map.kind]+' · '+G.worldPhase().label+' · '+(map.kind==='town'?T.safe:G.inCombat()?T.combat:T.explore);$('gold-count').textContent=s.gold;$('point-count').textContent=s.points||'';$('point-count').hidden=!s.points;$('potion-count').textContent=s.potions;updateStatus();$('potion-cooldown').style.height=Math.max(0,(p.potionAt-s.time)/C.potionCooldown*C.percentage)+'%';const nearby=G.nearby();$('interaction-name').textContent=nearby?nearby.label:T.interact;$('interaction-action').textContent=nearby?nearby.kind==='npc'?DB.npcTypes[nearby.service].name:nearby.kind==='portal'?T.enter:nearby.kind==='chest'?T.open:nearby.kind==='discovery'?T.discover:nearby.kind==='event'?T.worldEvent:nearby.kind==='mechanism'?T.mechanism:T.gather:T.noInteraction;$('play-stage').classList.toggle('has-context',!!nearby);const track=G.trackedQuest();$('quest-type').textContent=track?.quest.main?T.mainQuest:T.sideQuest;$('quest-title').textContent=track?.quest.name||T.storyComplete;$('quest-line').textContent=track?.line||DB.world.goal;const route=track?.map?G.routeTo(track.map):[];$('quest-route').textContent=route.length?T.routeNext+' · '+route[0].name:track?.status==='ready'?T.readyToClaim:map.name;const boss=G.instance().enemies.find(e=>DB.monsters[e.template].boss&&!e.dead);$('boss-hud').hidden=!boss;if(boss){$('boss-name').textContent=DB.monsters[boss.template].name+' · '+T.level+boss.level+' · '+T.phase+' '+(boss.phase+1);$('boss-health').textContent=Math.ceil(boss.hp)+' / '+Math.ceil(boss.maxHp)+(G.wardCount()?' · '+T.bossWards+' '+G.wardCount():'');$('boss-fill').style.width=Math.max(0,boss.hp/boss.maxHp*C.percentage)+'%';}const remaining=G.guardiansRemaining();const event=map.events.map(e=>G.eventStatus(e.id)).find(e=>['active','waiting','ready'].includes(e.phase));$('map-objective').hidden=!map.guardianTotal&&!event&&!s.trial;$('map-objective').textContent=map.guardianTotal?T.guardians+' '+(map.guardianTotal-remaining)+' / '+map.guardianTotal:event?event.definition.name+' · '+(event.phase==='ready'?T.eventReady:T.eventRemaining+' '+event.remaining):s.trial?find(DB.trials,s.trial.id).name+' · '+T.wave+' '+Math.min(s.trial.wave+1,find(DB.trials,s.trial.id).waves.length)+'/'+find(DB.trials,s.trial.id).waves.length:'';$('loot-feed').innerHTML=s.lootFeed.map(l=>`<div style="--rarity:${find(DB.rarities,l.rarity).color}">${icon('bag')}<span>${esc(l.name)}</span></div>`).join('');$('world-notices').innerHTML=s.notices.map(n=>`<div class="${n.kind}">${esc(n.text)}</div>`).join('');updateAutoSkills();}
function updateAutoSkills(){const s=G.state(),p=s.player,parent=$('auto-skills'),key=s.skills.map(id=>id||'').join(':');if(parent.dataset.skills!==key){parent.dataset.skills=key;parent.innerHTML=s.skills.map((id,i)=>{const skill=DB.skills[id];return button('skills',`${icon(skill?.icon||chIcon())}<span><small>${esc(T.auto)}</small><strong>${esc(skill?.name||T.skillEmpty)}</strong></span><b id="auto-cooldown-${i}"></b>`,{index:i},'auto-skill');}).join('');}for(const [i,id]of s.skills.entries()){const left=id?Math.max(0,(p.skillCooldowns[id]||0)-s.time):0;$('auto-cooldown-'+i).textContent=left>0?num(left):id?T.ready:'';}}
function keyLabel(action){return DB.controlLabels[action]||(DB.controls[action]?.[0]||'').replace('Key','').replace('Digit','');}
function timeLabel(seconds){const whole=Math.max(0,Math.ceil(seconds));return Math.floor(whole/C.secondsPerMinute)+':'+String(whole%C.secondsPerMinute).padStart(2,'0');}
function movementInput(){const active=dir=>DB.controls[dir].some(code=>keys.has(code));return {x:(active('right')?1:0)-(active('left')?1:0)+stick.x,y:(active('down')?1:0)-(active('up')?1:0)+stick.y};}
function dashButton(){return `<button id="dash-button" data-action="dash" class="dash-button" aria-label="${esc(T.dashHint)}" title="${esc(T.dashHint)}">${icon('dash')}<strong id="dash-count"></strong><small>${esc(keyLabel('dash'))}</small><span id="dash-clock"></span><i id="dash-progress"></i></button>`;}
function updateStatus(){const s=G.state(),info=G.blessingInfo(),bar=$('blessing-indicator');bar.hidden=!info;if(info){$('blessing-name').textContent=info.name;$('blessing-time').textContent=timeLabel(info.remaining);bar.title=info.description+' · '+T.blessingRemaining+' '+timeLabel(info.remaining);}const dash=G.dashInfo(),p=s.player;$('dash-count').textContent=dash.charges+' / '+dash.max;$('dash-clock').textContent=dash.charges<dash.max?num(Math.max(0,p.dashReadyAt-s.time))+'s':'';$('dash-progress').style.height=dash.charges<dash.max?Math.max(0,(p.dashReadyAt-s.time)/C.dashCooldown*C.percentage)+'%':'0%';$('dash-button').disabled=dash.charges===0||p.dashUntil>s.time;$('dash-button').classList.toggle('empty',dash.charges===0);$('play-stage').dataset.phase=G.worldPhase().night?'night':'day';}
function blessingBody(){const info=G.blessingInfo(),s=G.state();return `<section class="blessing-state ${info?'active':''}"><small>${esc(T.blessingCurrent)}</small>${info?`<h3>${esc(info.name)} ${tag(T.blessingOne,'positive')}</h3>${changes(info.stats)}<p>${esc(T.blessingRemaining)} <strong>${timeLabel(info.remaining)}</strong></p>`:`<p>${esc(T.blessingNone)}</p>`}</section><p>${esc(T.blessingHint)}</p><div class="blessing-grid">${DB.blessings.map(b=>{const on=info?.id===b.id,full=on&&info.remaining>=b.duration-C.blessingRefreshTolerance;return `<article class="service-card ${on?'active-blessing':''}">${icon('heart')}<h3>${esc(b.name)}</h3><p>${esc(b.description)}</p>${on?tag(T.blessingApplied+' · '+timeLabel(info.remaining),'positive'):''}${button('bless',full?T.blessingApplied:`${on?T.blessingRefresh:T.blessing} · ${b.cost} ${T.gold}`,{id:b.id},'primary',full||s.gold<b.cost)}</article>`;}).join('')}</div>`;}
function shopBody(){const s=G.state(),npc=currentNpc,goods=G.shopInventory(npc).filter(i=>i.kind===shopFilter);return `${wallet()}<p>${T.merchantHint}</p><nav class="filter-tabs">${[['consumable',T.shopConsumables],['equipment',T.shopEquipment],['material',T.shopMaterials]].map(([id,label])=>button('shop-filter',label,{id},shopFilter===id?'selected':'')).join('')}</nav><div class="shop-grid">${goods.map(i=>{const stock=G.shopStatus(i,npc),rarity=i.rarity&&find(DB.rarities,i.rarity);return `<article class="shop-card">${icon(i.icon)}<div><h3>${esc(i.name)}</h3><p>${esc(i.description)}</p>${rarity?tag(rarity.name+' · '+T.level+i.level):''}${stock.remaining!==null?`<small>${T.stockLeft} ${stock.remaining}/${i.limit}</small>`:''}</div>${button('buy',stock.locked?G.text('shopLevelGate',{level:i.minLevel}):stock.remaining===0?T.soldOut:`${i.price} ${T.gold} · ${T.buy}`,{id:i.id},'primary',stock.locked||stock.remaining===0||s.gold<i.price)}</article>`;}).join('')}</div>${button('inventory',T.sellItems,{},'full')}`;}
function suppliesBody(){const s=G.state();return `<div class="supplies-grid">${DB.consumables.map(c=>{const count=G.consumableCount(c.id),left=Math.max(0,(s.player.consumableReady[c.id]||0)-s.time),hotkey=c.id===C.healingConsumable?keyLabel('potion'):c.id===C.manaConsumable?keyLabel('manaPotion'):'';return `<article class="supply-card"><span>${icon(c.icon)}</span><div><h3>${esc(c.name)} ${hotkey?tag(hotkey):''}</h3><p>${esc(c.description)}</p><small>${T.held} ${count}</small></div>${button('use-supply',left>0?num(left)+'s':T.use,{id:c.id},'primary',count<=0||left>0)}</article>`;}).join('')}</div><small class="muted-note">${T.supplyHint}</small>`;}
function explorationLog(){const s=G.state();return `<details class="exploration-log"><summary>${esc(T.explorationLog)} · ${Object.keys(s.discoveries).filter(id=>s.discoveries[id]).length} / ${Object.values(DB.maps).reduce((n,m)=>n+m.discoveries.length,0)}</summary><div>${Object.values(DB.maps).flatMap(m=>m.discoveries.map(d=>`<article class="${s.discoveries[d.id]?'found':''}"><small>${esc(m.name)}</small><h4>${esc(s.seenDiscoveries[d.id]||s.discoveries[d.id]?d.name:T.discoverUnknown)}</h4>${s.discoveries[d.id]?`<p>${esc(d.description)}</p>${d.stats?changes(d.stats):''}`:`<small>${esc(s.seenDiscoveries[d.id]?T.discoverSeen:T.unvisited)}</small>`}</article>`)).join('')}</div></details>`;}
function worldBody(){const n=worldInteraction,s=G.state();if(n.kind==='discovery'){const found=!!s.discoveries[n.id];return `<div class="discovery-body"><span>${icon(n.kind==='shrine'?'heart':'signature')}</span><h3>${esc(n.name)}</h3><p>${esc(n.description)}</p>${n.stats?`<h4>${T.permanent}</h4>${changes(n.stats)}`:''}${rewardHTML(n.rewards||{})}${button('discover',found?T.discovered:T.discover,{id:n.id},'primary full',found)}</div>`;}const state=G.eventStatus(n.id);return `<div class="discovery-body"><span>${icon('fight')}</span><h3>${esc(n.name)}</h3><p>${esc(n.description)}</p>${rewardHTML(n.rewards)}${state.phase==='idle'?`<p class="event-warning">${T.eventDanger}</p>${button('start-event',T.eventStart,{id:n.id},'primary full')}`:['active','waiting'].includes(state.phase)?`<p>${G.text('eventWave',{wave:(state.wave||0)+1,total:(n.waves||[n.spawns]).length})}</p><p>${T.eventRemaining} <strong>${state.remaining}</strong></p>${button('close',T.resume,{},'primary full')}`:state.phase==='ready'?button('claim-event',T.eventClaim,{id:n.id},'primary full'):`<p>${T.eventCooldown} · ${timeLabel(Math.max(0,state.until-s.time))}</p>`}</div>`;}
function openWorldInteraction(n){worldInteraction=n;openModal('world',n.kind==='discovery'?T.discovery:T.worldEvent,worldBody());}
function chIcon(){return find(DB.classes,G.state().classId).icon;}
function wallet(){const s=G.state();return `<div class="menu-wallet"><span>${icon('coins')}<b>${s.gold}</b> ${esc(T.gold)}</span>${DB.materials.map(m=>`<span>${icon(m.icon)}<b>${s.materials[m.id]}</b> ${esc(m.name)}</span>`).join('')}</div>`;}
function comparison(after,before=G.stats(),title=T.compare){const keys=DB.comparisonStats.filter(k=>Math.abs(after[k]-before[k])>Number.EPSILON).slice(0,C.comparisonLimit);return `<div class="comparison"><h4>${icon('compare')}${esc(title)}</h4>${keys.map(k=>`<div class="${(after[k]-before[k])*(DB.statDirections[k]||1)>0?'positive':'negative'}"><span>${esc(DB.statLabels[k])}</span><small>${esc(statValue(k,before[k]))}</small><i>→</i><strong>${esc(statValue(k,after[k]))}</strong></div>`).join('')||`<small>${esc(T.noChange)}</small>`}</div>`;}

function openInteraction(n){if(n.kind==='discovery'||n.kind==='event')openWorldInteraction(n);else if(n.kind==='dungeon'){entryPortal=n;expeditionRule=DB.expeditionRules[0].id;openModal('dungeon',T.dungeonEntry,dungeonBody(),true);}else openNpc(n);}
function itemTraits(item){const def=find(DB.items,item.template),element=find(DB.elements,(item.rune&&find(DB.runes,item.rune)?.element)||def.element||DB.elements[0].id),set=def.set&&find(DB.equipmentSets,def.set);return `<div class="item-traits">${def.slot==='weapon'?tag(T.element+' · '+element.name):''}${item.bound?tag(T.bound):item.origin==='server'?tag(T.tradeable):''}${item.rune?tag(T.itemRune+' · '+find(DB.runes,item.rune).name):''}${set?tag(T.setEffect+' · '+set.name):''}</div>${set?`<details class="set-bonuses"><summary>${esc(set.name)}</summary>${set.bonuses.map(b=>`<small>${T.setEffect} · ${b.count}</small>${changes(b.stats)}`).join('')}</details>`:''}`;}
function runeSmithBody(){const s=G.state();let item=s.inventory.find(i=>i.id===selectedItem);if(!item||find(DB.items,item.template).slot!=='weapon')item=s.inventory.find(i=>i.id===s.equipment.weapon);selectedItem=item?.id;return `${wallet()}<nav class="filter-tabs">${button('smith-tab',T.enhance,{id:'enhance'})}${button('smith-tab',T.craft,{id:'craft'})}${button('smith-tab',T.engrave,{id:'engrave'},'selected')}</nav><p>${T.engraveHint}</p><div class="smith-layout"><section class="bag-grid smith-items">${s.inventory.filter(i=>find(DB.items,i.template).slot==='weapon').map(i=>itemCard(i,'smith-item')).join('')}</section><section>${item?`<h3>${esc(G.itemName(item))}</h3>${itemTraits(item)}<div class="rune-grid">${DB.runes.map(r=>`<article><h4>${esc(r.name)}</h4><p>${esc(r.description)}</p>${button('engrave',`${T.engrave} · ${r.gold} ${T.gold}`,{id:r.id,item:item.id},'primary',s.gold<r.gold||Object.entries(r.materials).some(([id,n])=>s.materials[id]<n))}</article>`).join('')}</div>`:`<p>${T.engraveChoose}</p>`}</section></div>`;}

function itemCard(item,action='item',equipped=true){const def=find(DB.items,item.template),rarity=find(DB.rarities,item.rarity),on=Object.values(G.state().equipment).includes(item.id);return button(action,`<span class="item-art">${icon(def.icon)}</span><span class="item-name">${esc(G.itemName(item))}</span><small>${T.level}${item.level} · ${esc(rarity.name)}</small>${on&&equipped?`<b class="equipped-mark">${icon('check')}${T.equipped}</b>`:''}`,{id:item.id},`item-card ${on?'equipped':''} ${selectedItem===item.id?'selected':''}`).replace('<button ','<button style="--rarity:'+rarity.color+'" ');}
function itemDetailBody(item,back=false){if(!item)return `<p>${T.equipFirst}</p>`;const s=G.state(),def=find(DB.items,item.template),rarity=find(DB.rarities,item.rarity),on=Object.values(s.equipment).includes(item.id);return `<div class="item-detail-heading" style="--rarity:${rarity.color}"><span>${icon(def.icon)}</span><small>${esc(rarity.name)} · ${esc(find(DB.slots,def.slot).name)} · ${T.level}${item.level}</small><h3>${esc(G.itemName(item))}</h3></div><p>${esc(def.description)}</p>${itemTraits(item)}${changes(G.itemStats(item))}${comparison(G.previewItem(item))}<div class="detail-actions">${button(on?'unequip':'equip',on?T.unequip:T.equip,{id:on?def.slot:item.id},'primary full')}${button('favorite',item.favorite?T.unfavorite:T.favorite,{id:item.id},'full')}<div>${button('salvage',T.salvage,{id:item.id},'',on||item.favorite||G.mapDef().kind!=='town')}${button('sell',T.sell,{id:item.id},'',on||item.favorite||G.mapDef().kind!=='town')}</div>${back?button('inventory',T.inventoryBack,{},'full'):''}</div><small class="muted-note">${esc(T.upgradeNpcHint)}</small>`;}
function openItem(){const item=G.state().inventory.find(i=>i.id===selectedItem);if(!item){openInventory();return;}openModal('item',T.itemDetail,`<aside class="item-detail">${itemDetailBody(item,true)}</aside>`);}
function inventoryBody(){const s=G.state();if(!s.inventory.some(i=>i.id===selectedItem))selectedItem=s.equipment.weapon||s.inventory[0]?.id;const item=s.inventory.find(i=>i.id===selectedItem),def=item&&find(DB.items,item.template),rarity=item&&find(DB.rarities,item.rarity),on=item&&Object.values(s.equipment).includes(item.id);return `${wallet()}<div class="inventory-layout ${bagFilter==='supplies'?'supplies-layout':''}"><aside class="equipment-column"><div class="paper-hero">${window.RPGArt.heroPortrait(s.raceId,s.classId)}<div><strong>${esc(s.name)}</strong><small>${T.level}${s.level} · ${esc(find(DB.classes,s.classId).name)}</small></div></div><h3>${esc(T.equippedCount)}</h3><div class="equipment-slots">${DB.slots.map(slot=>{const current=s.inventory.find(i=>i.id===s.equipment[slot.id]);return `<section><small>${icon(slot.icon)}${esc(slot.name)}</small>${current?button('item',`<strong>${esc(G.itemName(current))}</strong><small>${esc(find(DB.rarities,current.rarity).name)} · ${T.level}${current.level}</small>`,{id:current.id},'worn-item'): `<span class="empty-item">${T.emptySlot}</span>`}</section>`;}).join('')}</div><details><summary>${esc(T.playerStats)}</summary><div class="stat-grid">${DB.comparisonStats.map(k=>`<span>${esc(DB.statLabels[k])}<b>${esc(statValue(k,G.stats()[k]))}</b></span>`).join('')}</div></details></aside><section class="bag-column"><nav class="filter-tabs">${[{id:'all',name:T.all},...DB.slots,{id:'supplies',name:T.supplies}].map(slot=>button('bag-filter',esc(slot.name),{id:slot.id},bagFilter===slot.id?'selected':'')).join('')}</nav>${bagFilter==='supplies'?suppliesBody():`<div class="bag-grid">${[...s.inventory].filter(i=>bagFilter==='all'||find(DB.items,i.template).slot===bagFilter).sort((a,b)=>G.itemScore(b)-G.itemScore(a)).slice(0,C.inventorySortLimit).map(i=>itemCard(i)).join('')||`<p>${T.noItems}</p>`}</div>`}</section>${bagFilter!=='supplies'?`<aside class="item-detail">${itemDetailBody(item)}</aside>`:''}</div>`;}
function openInventory(){openModal('inventory',T.bag,inventoryBody(),true);}
function talentBody(){
 const s=G.state(),ch=find(DB.classes,s.classId),path=G.selectedBranches();
 const lineage=`<section class="advancement-lineage"><h3>${T.growthStages}</h3><p>${T.advancementHint}</p>${s.advancementRefund?`<p class="positive">${esc(G.text('branchRefund',{points:s.advancementRefund}))}</p>`:''}<div class="advancement-stages">${DB.advancementStages.map(stage=>{const selected=DB.branches[s.advancements[stage.id]],options=G.advancementOptions(stage.id);return `<section><header><b>${stage.name}</b><small>${G.text('advancementLevel',{level:stage.level})}${stage.requiredPoints?' · '+G.text('growInvest',{count:stage.requiredPoints}):''}</small></header>${selected?`<article class="advancement-choice chosen"><h4>${esc(selected.name)}</h4><p>${esc(selected.description)}</p>${tag(T.chosenAdvancement,'positive')}</article>`:options.length?options.map(b=>`<article class="advancement-choice"><h4>${esc(b.name)}</h4><p>${esc(b.description)}</p>${changes(DB.talents.filter(n=>n.branch===b.id).flatMap(n=>n.stats).slice(0,C.advancementPreviewStats))}${button('advance',T.chooseAdvancement,{id:b.id},'primary',s.level<b.level||G.mapDef().kind!=='town'||b.parent&&G.branchPoints(b.parent)<stage.requiredPoints)}</article>`).join(''):`<p class="muted-note">${T.advancementLocked}</p>`}</section>`;}).join('')}</div></section>`;
 return `<div class="build-header"><div class="paper-hero">${window.RPGArt.heroPortrait(s.raceId,s.classId)}<div><strong>${esc(DB.branches[s.advancements[3]||s.advancements[2]||s.advancements[1]]?.name||ch.name)}</strong><small>${esc(ch.role)}</small></div></div><div class="points-budget"><strong>${s.points}</strong><small>${T.talentPoints}</small></div>${button('ask-respec',G.text('respecPaid',{gold:C.advancementRespecCost}),{},'',G.mapDef().kind!=='town'||s.gold<C.advancementRespecCost)}</div><nav class="filter-tabs">${button('talent-tab',T.treeTab,{id:'tree'},talentTab==='tree'?'selected':'')}${button('talent-tab',T.skillTab,{id:'skills'},talentTab==='skills'?'selected':'')}</nav>${talentTab==='tree'?lineage+`<div class="talent-branches route-talents">${path.map(id=>{const b=DB.branches[id];return `<section class="talent-branch"><header><span>${G.branchPoints(id)}</span><h3>${esc(b.name)}</h3><p>${T.rankGrowth}</p></header>${DB.talents.filter(n=>n.branch===id).map(node=>{const rank=s.talents[node.id]||0,locked=G.branchPoints(id)<node.requires||s.level<(node.minLevel||1),maxed=rank>=node.maxRank;return `<article class="talent-node ${rank?'invested':''}"><div><h4>${esc(node.name)}</h4><b>${rank}/${node.maxRank}</b></div>${changes(node.stats)}<small>${G.text('talentLevel',{level:node.minLevel||1})} · ${G.text('requiresBranch',{count:node.requires})}</small>${button('learn',maxed?T.learned:`${T.learn} · ${node.cost}`,{id:node.id},rank?'':'primary',locked||maxed||s.points<node.cost)}</article>`;}).join('')}</section>`;}).join('')}</div><small class="muted-note">${T.respecHint}</small>`:`<p>${T.skillsSubtitle}</p><div class="skill-slots">${s.skills.map((id,i)=>button('skill-slot',`<small>${T.skillSlot} ${i+1}</small><strong>${esc(DB.skills[id]?.name||T.skillEmpty)}</strong>`,{index:i},i===skillSlot?'selected':'')).join('')}</div><div class="skill-catalog">${ch.skills.filter(id=>!DB.skills[id].requiredBranch||G.selectedBranches().includes(DB.skills[id].requiredBranch)).map(id=>{const skill=DB.skills[id],locked=!G.skillAllowed(skill),on=s.skills.includes(id);return `<article class="skill-card"><span>${icon(skill.icon)}</span><div><h3>${esc(skill.name)}</h3><p>${esc(T['skillKind_'+skill.kind])}</p><small>${T.manaCost} ${skill.cost} · ${T.cooldown} ${skill.cooldown}${T.sfxUnit}</small>${skill.element?tag(T.skillElement+' · '+find(DB.elements,skill.element).name):''}${skill.party?tag(T.partySupport):''}${skill.burn?tag(T.burn):''}${skill.slow?tag(T.slow):''}</div>${button('equip-skill',locked?G.text('skillUnlock',{level:skill.unlock}):on?T.equipped:T.equip,{id},on?'':'primary',locked||on)}</article>`;}).join('')}</div>`}`;
}
function openTalents(){openModal('talents',T.talents,talentBody(),true);}
function rewardHTML(reward){return `<div class="quest-rewards">${reward.gold?`<span>${icon('coins')}+${reward.gold}</span>`:''}${reward.xp?`<span>+${reward.xp} ${T.xp}</span>`:''}${reward.points?`<span>+${reward.points} ${T.points}</span>`:''}${reward.potions?`<span>${icon('potion')}+${reward.potions}</span>`:''}${Object.entries(reward.materials||{}).map(([id,n])=>`<span>${esc(find(DB.materials,id).name)} +${n}</span>`).join('')}${Object.entries(reward.supplies||{}).map(([id,n])=>`<span>${esc(find(DB.consumables,id).name)} +${n}</span>`).join('')}${Object.entries(reward.reputation||{}).map(([id,n])=>`<span>${esc(find(DB.factions,id).name)} +${n}</span>`).join('')}${reward.companion?`<span>${T.companions} · ${esc(find(DB.companions,reward.companion).name)}</span>`:''}</div>`;}
function questCard(q,atNpc=false){const status=G.questStatus(q.id),r=G.state().quests[q.id],ready=status==='ready',available=status==='available';return `<article class="quest-card ${ready?'ready':''}"><header><span>${tag(q.main?T.mainQuest:q.repeatable?T.repeatable:T.sideQuest)}</span><h3>${esc(q.name)}</h3>${tag(T[status]||T.active,ready?'positive':'')}</header><p>${esc(q.description)}</p><ul>${q.objectives.map((o,i)=>`<li><span>${esc(o.label)}</span><strong>${status==='complete'?o.count:available?0:G.objectiveProgress(q,i)} / ${o.count}</strong></li>`).join('')}</ul>${rewardHTML(q.rewards)}${r?.choice?tag(T.choiceSaved+' · '+q.choices.find(c=>c.id===r.choice)?.name):''}${atNpc&&available?button('accept',T.accept,{id:q.id},'primary'):atNpc&&ready?q.choices?`<strong>${T.choiceReward}</strong><div class="reward-choices">${q.choices.map(c=>button('claim',`<strong>${esc(c.name)}</strong><small>${esc(c.description)}</small>`,{id:q.id,choice:c.id},'')).join('')}</div>`:button('claim',T.claim,{id:q.id},'primary'):status==='cooling'?`<small>${G.text('questCooldown',{time:Math.ceil((r.completedAt||0)+(q.cooldown||C.questRepeatCooldown)-G.state().time)})}</small>`:status!=='complete'?button('quest-map',ready?T.returnNpc:T.moveTo,{id:q.id}):''}</article>`;}
function questBody(){const s=G.state(),tabs=`<nav class="filter-tabs journal-tabs">${DB.journalTabs.map(t=>button('journal-tab',t.name,{id:t.id},journalTab===t.id?'selected':'')).join('')}</nav>`;if(journalTab==='companions')return tabs+companionsBody();if(journalTab==='factions')return tabs+factionBody();if(journalTab==='codex')return tabs+codexBody();const list=DB.quests.filter(q=>['active','ready','available','cooling'].includes(G.questStatus(q.id))&&(q.main||G.questStatus(q.id)!=='available')&&(questFilter==='all'||questFilter==='main'&&q.main||questFilter==='side'&&!q.main&&!q.repeatable||questFilter==='repeat'&&q.repeatable)),pages=Math.max(1,Math.ceil(list.length/C.questListPage));questPage=Math.min(questPage,pages-1);return tabs+`<p class="muted-note">${T.journalHint}</p><nav class="filter-tabs">${[['all',T.questFilterAll],['main',T.questFilterMain],['side',T.questFilterSide],['repeat',T.questFilterRepeat]].map(([id,label])=>button('quest-filter',label,{id},questFilter===id?'selected':'')).join('')}</nav><div class="quest-journal">${list.slice(questPage*C.questListPage,(questPage+1)*C.questListPage).map(q=>questCard(q,G.nearby()?.id===q.npc&&G.nearby()?.kind==='npc')).join('')||`<p>${T.questEmpty}</p>`}</div><div class="pagination">${button('quest-page',T.previous,{index:questPage-1},'',questPage===0)}<small>${questPage+1} / ${pages}</small>${button('quest-page',T.next,{index:questPage+1},'',questPage>=pages-1)}</div><details class="completed-list"><summary>${T.completedQuests} · ${DB.quests.filter(q=>!q.repeatable&&G.questStatus(q.id)==='complete').length}/${DB.quests.filter(q=>!q.repeatable).length}</summary>${DB.quests.filter(q=>!q.repeatable&&G.questStatus(q.id)==='complete').map(q=>`<p>${icon('check')}${esc(q.name)}${s.choices[q.id]?' · '+esc(q.choices?.find(c=>c.id===s.choices[q.id])?.name):''}</p>`).join('')}</details>`;}

function companionsBody(){const s=G.state();return `<p>${T.companionHint}</p><div class="companion-grid">${DB.companions.map(c=>{const unlocked=s.companions[c.id]?.unlocked,on=s.companionId===c.id;return `<article class="service-card"><span class="companion-portrait">${icon(c.mode==='heal'?'heart':c.mode==='shield'?'shield':'staff')}</span><small>${esc(c.role)}</small><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p>${changes(c.stats)}${unlocked?`<small>${T.bond} ${s.companions[c.id].bond||0}/${C.companionBondCap}</small>${button('select-companion',on?T.companionActive:T.companionSelect,{id:c.id},on?'':'primary',on||G.mapDef().kind!=='town')}`:`<small>${T.companionLocked}</small>${button('quest-map',T.moveTo,{id:c.quest})}`}</article>`;}).join('')}</div>${button('select-companion',T.companionNone,{id:''},'full',!s.companionId||G.mapDef().kind!=='town')}`;}
function factionBody(){return `<p>${T.factionHint}</p><div class="faction-grid">${DB.factions.map(f=>{const info=G.reputationStatus(f.id);return `<article class="service-card">${icon(f.icon)}<h3>${esc(f.name)}</h3><p>${esc(f.description)}</p><strong>${esc(info.rank.name)} · ${info.value}</strong>${info.next?`<div class="meter"><i style="width:${Math.min(C.percentage,info.value/info.next.value*C.percentage)}%"></i></div><small>${info.next.value} · ${esc(info.next.name)}</small>`:''}<p>${esc(find(DB.recipes,'faction_'+f.id).name)} · ${T.reputation} 120</p></article>`;}).join('')}</div>`;}
function codexBody(){const s=G.state();return `<p>${T.codexHint}</p><div class="codex-grid">${Object.entries(DB.monsters).filter(([,m])=>!m.ignoreCodex).map(([id,m])=>{const kills=s.killCounts[id]||0;return `<article><small>${m.boss?T.boss:m.elite?T.elite:T.monster}</small><h3>${esc(m.name)}</h3>${tag(T.element+' · '+find(DB.elements,m.element||DB.elements[0].id).name)}<p>${esc(T['pattern_'+(m.kind||m.patterns?.[0]?.kind)]||T.boss)}</p><b>${T.defeated} ${kills}</b><div>${DB.codexRewards.map((r,index)=>button('codex-claim',`${r.kills} · ${s.codexClaims[id+':'+index]?T.complete:T.codexClaim}`,{id,index},'',kills<r.kills||!!s.codexClaims[id+':'+index])).join('')}</div></article>`;}).join('')}</div>`;}
function arenaBody(){const s=G.state(),run=s.trial,def=run&&find(DB.trials,run.id);if(def&&G.mapDef().id===def.map)return `<div class="service-card"><h3>${esc(def.name)}</h3><p>${T.wave} ${Math.min(run.wave+1,def.waves.length)}/${def.waves.length}</p><p>${T.trialExit}</p>${rewardHTML(def.rewards)}${run.phase==='ready'?button('claim-trial',T.trialClaim,{},'primary'):run.phase==='claimed'?tag(T.trialClaimed,'positive'):button('close',T.resume,{},'primary')}</div>`;return `${wallet()}<div class="trial-grid">${DB.trials.map(t=>`<article class="service-card"><h3>${esc(t.name)}</h3><small>${T.level}${t.minLevel} · ${t.waves.length} ${T.wave}</small><p>${esc(t.description)}</p>${rewardHTML(t.rewards)}${button('start-trial',`${T.trialStart} · ${t.fee} ${T.gold}`,{id:t.id},'primary',s.level<t.minLevel||s.gold<t.fee)}</article>`).join('')}</div>`;}

function openQuests(){openModal('quests',T.quests,questBody(),true);}
function mapBody(){const s=G.state(),track=G.trackedQuest();regionFilter??=DB.regions.find(r=>r.maps.includes(s.mapId))?.id||'east';return `<nav class="filter-tabs">${[{id:'all',name:T.allRegions},...DB.regions].map(r=>button('map-region',r.name,{id:r.id},regionFilter===r.id?'selected':'')).join('')}</nav><p>${esc(T.travelHint)}</p><div class="world-map-cards">${Object.values(DB.maps).filter(m=>regionFilter==='all'||find(DB.regions,regionFilter)?.maps.includes(m.id)).map(map=>{const visited=s.visited[map.id],current=map.id===s.mapId,target=mapFocus===map.id||track?.map===map.id,route=G.routeTo(map.id),gate=Object.values(DB.maps).flatMap(m=>m.portals).find(p=>p.to===map.id&&p.requiresQuest),locked=gate&&s.quests[gate.requiresQuest]?.status!=='complete';return `<article class="map-card ${current?'current':''} ${target?'target':''} ${visited?'visited':''}"><span>${icon(map.kind==='town'?'home':map.kind==='field'?'tree':map.kind==='boss'?'signature':'portal')}</span><div><small>${esc(DB.mapKinds[map.kind])} · ${T.level}${map.level}</small><h3>${esc(map.name)}</h3><p>${esc(current?T.currentLocation:locked?G.text('requiresQuest',{quest:find(DB.quests,gate.requiresQuest).name}):route.length?T.routeNext+' · '+route[0].name:T.walking)}</p></div>${map.waypoint?button('travel',current?T.currentLocation:visited?T.travel:T.unvisited,{id:map.id},visited&&!current?'primary':'',current||!visited||!G.canTravel().ok):tag(visited?T.complete:T.unvisited)}</article>`;}).join('')}</div>${explorationLog()}`;}
function openMap(){openModal('map',T.mapTitle,mapBody(),true);}
function smithBody(){if(smithTab==='engrave')return runeSmithBody();const s=G.state();if(!s.inventory.some(i=>i.id===selectedItem))selectedItem=s.equipment.weapon;const item=s.inventory.find(i=>i.id===selectedItem),cost=item&&G.upgradeCost(item),maxed=item&&item.enhance>=C.upgradeMax;return `${wallet()}<p>${esc(T.smithHint)}</p><nav class="filter-tabs">${button('smith-tab',T.enhance,{id:'enhance'},smithTab==='enhance'?'selected':'')}${button('smith-tab',T.craft,{id:'craft'},smithTab==='craft'?'selected':'')}${button('smith-tab',T.engrave,{id:'engrave'},smithTab==='engrave'?'selected':'')}</nav>${smithTab==='enhance'?`<div class="smith-layout"><section class="bag-grid smith-items">${[...s.inventory].sort((a,b)=>G.itemScore(b)-G.itemScore(a)).map(i=>itemCard(i,'smith-item')).join('')}</section><aside class="smith-detail">${item?`<span class="eyebrow">${T.enchantLevel} ${item.enhance} / ${C.upgradeMax}</span><h3>${esc(G.itemName(item))}</h3>${changes(G.itemStats(item))}${!maxed?comparison(G.previewItem({...item,enhance:item.enhance+1}),G.previewItem(item),T.upgradePreview):''}<p>${esc(T.upgradeHint)}</p>${button('upgrade',maxed?T.maxUpgrade:`${T.upgrade} · ${cost.gold} ${T.gold} / ${cost.ore} ${find(DB.materials,'ore').name}`,{id:item.id},'primary full',maxed||s.gold<cost.gold||s.materials.ore<cost.ore)}`:''}</aside></div>`:`<div class="recipe-grid">${DB.recipes.filter(r=>!r.classes||r.classes.includes(s.classId)).map(r=>`<article class="recipe-card"><span>${icon('anvil')}</span><h3>${esc(r.name)}</h3><p>${esc(r.description||find(DB.items,r.item).description)}</p>${r.reputation?`<small>${Object.entries(r.reputation).map(([id,n])=>esc(find(DB.factions,id).name)+' '+n).join(' · ')}</small>`:''}<div class="recipe-cost"><span>${r.gold} ${T.gold}</span>${Object.entries(r.materials).map(([id,n])=>`<span>${esc(find(DB.materials,id).name)} ${n}</span>`).join('')}</div>${button('craft',s.level<(r.minLevel||1)?G.text('craftLevelGate',{level:r.minLevel}):T.craft,{id:r.id},'primary',s.level<(r.minLevel||1)||!G.reputationAllowed(r.reputation)||s.gold<r.gold||Object.entries(r.materials).some(([id,n])=>s.materials[id]<n))}</article>`).join('')}</div>`}`;}
function npcBody(){const n=currentNpc,s=G.state();if(n.service==='arena')return arenaBody();if(n.service==='companion'){const c=DB.companions.find(c=>c.npc===n.id);return s.companions[c.id]?.unlocked?companionsBody():questCard(find(DB.quests,c.quest),true);}if(n.service==='guild'||n.service==='board'){const list=DB.quests.filter(q=>q.npc===n.id&&['active','ready','available','cooling'].includes(G.questStatus(q.id)));return `<p>${esc(n.service==='guild'?DB.world.goal:T.journalHint)}</p><div class="quest-journal">${list.map(q=>questCard(q,true)).join('')||`<p>${T.noOffers}</p>`}</div>`;}if(n.service==='smith')return smithBody();if(n.service==='merchant')return shopBody();if(n.service==='inn')return `${wallet()}<div class="service-card">${icon('home')}<h3>${T.rest}</h3><p>${T.restHint}</p>${button('rest',G.text('restPaid',{gold:DB.inn.restCost}),{},'primary',s.gold<DB.inn.restCost)}</div><div class="service-card"><h3>${DB.inn.name}</h3><p>${DB.inn.description}</p>${changes(DB.inn.stats)}${button('meal',`${T.meal} · ${DB.inn.cost} ${T.gold}`,{},'primary',s.gold<DB.inn.cost)}</div>`;if(n.service==='temple')return `${wallet()}${blessingBody()}${button('talents',T.respec,{},'full')}`;return mapBody();}
function openNpc(n){if(currentNpc?.id!==n.id)shopFilter=n.vendorType==='wanderer'?'equipment':'consumable';currentNpc=n;openModal('npc',n.name+' · '+DB.npcTypes[n.service].name,npcBody(),['smith','guild','board','waystone','companion','arena','merchant'].includes(n.service));}
function dungeonBody(){const map=DB.maps[entryPortal.to],clears=G.state().clears[map.group]||0;return `<div class="dungeon-intro"><span>${icon('portal')}</span><h3>${esc(map.name)}</h3><p>${esc(T.dungeonGuardianHint)}</p><small>${T.clears} ${clears}</small></div><h4>${T.expeditionRule}</h4><nav class="expedition-rules">${DB.expeditionRules.map(r=>button('expedition-rule',`<strong>${esc(r.name)}</strong><small>${esc(r.description)}</small>`,{id:r.id},r.id===expeditionRule?'selected':'')).join('')}</nav><div class="dungeon-tiers">${DB.dungeonTiers.map(t=>`<article><h3>${esc(t.name)}</h3><p>${T.runLevel} ${map.level+t.levelBonus} · ${T.reward} ${t.reward}×</p><small>${esc(clears<t.requiredClears?G.text('tierLocked',{count:t.requiredClears}):T.rareReward)}</small>${button('enter-dungeon',T.enter,{tier:t.id},'primary',clears<t.requiredClears)}</article>`).join('')}</div><small class="muted-note">${T.tierHint}</small>`;}
function doInteract(){const r=G.interact();if(!result(r))return;if(r.interaction){if(r.interaction.kind==='discovery'||r.interaction.kind==='event'){openWorldInteraction(r.interaction);}else if(r.interaction.kind==='dungeon'){entryPortal=r.interaction;expeditionRule=DB.expeditionRules[0].id;openModal('dungeon',T.dungeonEntry,dungeonBody(),true);}else openNpc(r.interaction);}else{renderer?.resize();updateHUD();save();}}
function settingsBody(){return `<div class="settings-grid"><section><h3>${icon('music')}${T.music}</h3><label><span>${T.music}</span><input type="checkbox" data-pref="music" ${preferences.music?'checked':''}></label><input type="range" min="0" max="${C.percentage}" value="${preferences.musicVolume*C.percentage}" data-volume="musicVolume"><label><span>${T.effects}</span><input type="checkbox" data-pref="effects" ${preferences.effects?'checked':''}></label><input type="range" min="0" max="${C.percentage}" value="${preferences.effectVolume*C.percentage}" data-volume="effectVolume"><small>${T.musicHint}</small></section><section class="settings-actions">${button('fullscreen',`${icon('fullscreen')}${T.fullscreen}`)}${button('help',`${icon('quest')}${T.help}`)}${button('export',`${icon('save')}${T.save}`,{},'',!G.state())}${button('import',`${icon('load')}${T.load}`)}${scene==='game'?button('title',`${icon('home')}${T.returnToTitle}`):''}${button('new',T.newGame,{},'danger')}</section></div>`;}
function openSettings(){openModal('settings',T.settings,settingsBody(),false);}
function refreshModal(){const scroll=$('modal-scroll')?.scrollTop||0,kind=modalKind;if(kind==='inventory')openInventory();if(kind==='item')openItem();if(kind==='talents')openTalents();if(kind==='quests')openQuests();if(kind==='map')openMap();if(kind==='npc')openNpc(currentNpc);if(kind==='dungeon')openModal('dungeon',T.dungeonEntry,dungeonBody(),true);if(kind==='settings')openSettings();if(kind==='world')openWorldInteraction(worldInteraction);if($('modal-scroll'))$('modal-scroll').scrollTop=scroll;}
function askNew(){if(G.state())openModal('reset',T.resetTitle,`<p>${T.resetBody}</p><div class="button-row">${button('close',T.cancel)}${button('confirm-new',T.resetConfirm,{},'primary')}</div>`);else showCreation();}
function victory(){openModal('victory',T.chapterComplete,`<div class="victory-body">${icon('signature')}<h3>${esc(DB.world.completed)}</h3><p>${T.chapterVictory}</p>${button('close',T.chapterContinue,{},'primary')}</div>`,false);}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen){await document.documentElement.requestFullscreen({navigationUI:'hide'});if(window.matchMedia('(pointer:coarse)').matches)screen.orientation?.lock?.('landscape').catch(()=>{});}else toast(T.fullscreenUnavailable);renderer?.resize();}catch{toast(T.fullscreenUnavailable);}}
function exportSave(){if(!G.state())return;save();const blob=new Blob([JSON.stringify(G.snapshot(),null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=T.exportName;a.click();setTimeout(()=>URL.revokeObjectURL(url),C.noticeTime*C.milliseconds);toast(T.saved);}
function bindJoystick(){const zone=$('joystick');if(!zone)return;const update=event=>{const b=zone.getBoundingClientRect(),dx=(event.clientX-b.left-b.width/2)/C.joystickRadius,dy=(event.clientY-b.top-b.height/2)/C.joystickRadius,len=Math.max(1,Math.hypot(dx,dy));stick.x=dx/len;stick.y=dy/len;$('joystick-knob').style.transform=`translate(${stick.x*C.joystickRadius}px,${stick.y*C.joystickRadius}px)`;};zone.addEventListener('pointerdown',event=>{if(modalKind)return;A.unlock();event.preventDefault();joystickPointer=event.pointerId;zone.setPointerCapture(event.pointerId);update(event);});zone.addEventListener('pointermove',event=>{if(event.pointerId===joystickPointer){event.preventDefault();update(event);}});for(const type of ['pointerup','pointercancel','lostpointercapture'])zone.addEventListener(type,()=>{stick.x=0;stick.y=0;joystickPointer=null;$('joystick-knob').style.transform='translate(0,0)';});}
function handleAction(action,el){const id=el.dataset.id,index=Number(el.dataset.index);if(action.startsWith('online-')){window.RPGOnline?.handleAction(action,el);return;}if(window.RPGOnline?.isActive()){if(['new','confirm-new','import'].includes(action)){toast(T.onlineActionBlocked,true);return;}if(action==='title'){window.RPGOnline.logout();return;}if(DB.online.actionBindings[action]){window.RPGOnline.route(action,el,{id,index,skillSlot,entryPortal,expeditionRule,item:selectedItem,manaId:C.manaConsumable,input:movementInput()});return;}}if(action==='close'){closeModal();return;}if(action==='new')askNew();if(action==='confirm-new')showCreation();if(action==='title'){save();showTitle();}if(action==='continue')showGame();if(action==='race'){characterName=$('character-name')?.value||characterName;selectedRace=id;showCreation();}if(action==='class'){characterName=$('character-name')?.value||characterName;selectedClass=id;showCreation();}if(action==='start'){characterName=$('character-name')?.value||characterName;startGame();}if(action==='settings')openSettings();if(action==='help')openModal('help',T.help,`<p>${esc(T.helpBody)}</p><div class="help-controls">${icon('fight')}<strong>${esc(T.controls)}</strong><p>${esc(T.mobileControls)}</p></div>`);if(action==='fullscreen')fullscreen();if(action==='export')exportSave();if(action==='import')$('import-save').click();if(action==='advance')result(G.advance(id),true);if(action==='journal-tab'){journalTab=id;questPage=0;refreshModal();}if(action==='quest-filter'){questFilter=id;questPage=0;refreshModal();}if(action==='quest-page'){questPage=index;refreshModal();}if(action==='map-region'){regionFilter=id;refreshModal();}if(action==='select-companion')result(G.selectCompanion(id),true);if(action==='codex-claim')result(G.claimCodex(id,index),true);if(action==='expedition-rule'){expeditionRule=id;refreshModal();}if(action==='start-trial'){if(result(G.startTrial(id))){closeModal();renderer?.resize();updateHUD();}}if(action==='claim-trial')result(G.claimTrial(),true);if(action==='inventory')openInventory();if(action==='talents')openTalents();if(action==='quests')openQuests();if(action==='map'){mapFocus=null;openMap();}if(action==='potion')result(G.potion());if(action==='manaPotion')result(G.useConsumable(C.manaConsumable));if(action==='dash'){const input=movementInput();G.setInput(input.x,input.y);result(G.dash());}if(action==='use-supply')result(G.useConsumable(id),true);if(action==='shop-filter'){shopFilter=id;refreshModal();}if(action==='discover')result(G.discover(id),true);if(action==='start-event'){if(result(G.startEvent(id))){closeModal();updateHUD();}}if(action==='claim-event')result(G.claimEvent(id),true);if(action==='interact')doInteract();if(action==='item'){selectedItem=id;if(window.matchMedia(`(max-width: ${C.mobileMenuWidth}px)`).matches)openItem();else openInventory();}if(action==='bag-filter'){bagFilter=id;refreshModal();}if(action==='equip')result(G.equip(id),true);if(action==='unequip')result(G.unequip(id),true);if(action==='favorite')result(G.favorite(id),true);if(action==='salvage'||action==='sell')result(G.dispose(id,action),true);if(action==='talent-tab'){talentTab=id;refreshModal();}if(action==='learn')result(G.learn(id),true);if(action==='ask-respec')openModal('respec',T.respecConfirm,`<p>${T.respecConfirmHint}</p><div class="button-row">${button('talents',T.cancel)}${button('respec',T.respec,{},'primary')}</div>`);if(action==='respec'){if(result(G.respec()))openTalents();}if(action==='skills'){talentTab='skills';skillSlot=index;openTalents();}if(action==='skill-slot'){skillSlot=index;refreshModal();}if(action==='equip-skill')result(G.equipSkill(skillSlot,id),true);if(action==='accept')result(G.acceptQuest(id),true);if(action==='claim'){const r=G.completeQuest(id,el.dataset.choice);if(result(r,true)&&r.final)victory();}if(action==='quest-map'){const q=find(DB.quests,id),status=G.questStatus(id),npcMap=Object.values(DB.maps).find(m=>m.npcs.some(n=>n.id===q.npc));mapFocus=status==='ready'||status==='available'?npcMap?.id:q.objectives.find((o,i)=>G.objectiveProgress(q,i)<o.count)?.map;regionFilter=DB.regions.find(r=>r.maps.includes(mapFocus))?.id||regionFilter;openMap();}if(action==='travel'){if(result(G.travel(id))){closeModal();updateHUD();}}if(action==='smith-tab'){smithTab=id;refreshModal();}if(action==='smith-item'){selectedItem=id;refreshModal();}if(action==='upgrade')result(G.upgrade(id),true);if(action==='craft')result(G.craft(id),true);if(action==='buy')result(G.buy(id),true);if(action==='rest')result(G.rest(false),true);if(action==='meal')result(G.rest(true),true);if(action==='bless')result(G.bless(id),true);if(action==='enter-dungeon'){if(result(G.enterDungeon(entryPortal,Number(el.dataset.tier),expeditionRule))){closeModal();updateHUD();}}}
document.addEventListener('click',event=>{const el=event.target.closest?.('[data-action]');if(!el||el.disabled)return;A.unlock();A.play('click');handleAction(el.dataset.action,el);});
document.addEventListener('input',event=>{if(event.target.id==='character-name')characterName=event.target.value;if(event.target.dataset.volume){preferences[event.target.dataset.volume]=Number(event.target.value)/C.percentage;A.applyPreferences(preferences);try{localStorage.setItem(C.prefsKey,JSON.stringify(preferences));}catch{}}});
document.addEventListener('change',event=>{const key=event.target.dataset.pref;if(key){preferences[key]=event.target.checked;A.applyPreferences(preferences);try{localStorage.setItem(C.prefsKey,JSON.stringify(preferences));}catch{}}});
document.addEventListener('keydown',event=>{if(event.target.closest?.('input,textarea,select,[contenteditable=true]'))return;if(event.ctrlKey||event.metaKey||event.altKey)return;if(event.code==='Escape'){event.preventDefault();if(modalKind)closeModal();else if(scene==='game')openSettings();return;}if(scene==='game'&&DB.controls.inventory.includes(event.code)&&!event.shiftKey){event.preventDefault();if(!event.repeat){A.unlock();if(modalKind==='inventory'||modalKind==='item')closeModal();else openInventory();}return;}if(event.key==='Tab'&&modalKind){const nodes=[...$('modal').querySelectorAll('button:not(:disabled),input,select')],first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}if(scene!=='game'||modalKind)return;if(event.ctrlKey||event.metaKey||event.altKey)return;A.unlock();for(const dir of ['up','down','left','right'])if(DB.controls[dir].includes(event.code)){event.preventDefault();keys.add(event.code);return;}if(event.repeat)return;const action=Object.keys(DB.controls).find(k=>DB.controls[k].includes(event.code));if(action){event.preventDefault();handleAction(action,{dataset:{}});}});
$('modal-backdrop').addEventListener('click',event=>{if(event.target===$('modal-backdrop'))closeModal();});
document.addEventListener('keyup',event=>keys.delete(event.code));
$('import-save').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;if(window.RPGOnline?.isActive()){toast(T.onlineActionBlocked,true);event.target.value='';return;}try{const data=JSON.parse(await file.text()),r=G.load(data);if(!r.ok)throw Error(r.message);save();closeModal();showGame();toast(T.loaded);}catch(error){toast(error.message||T.invalidSave,true);}event.target.value='';});
window.addEventListener('resize',()=>renderer?.resize());window.visualViewport?.addEventListener('resize',()=>renderer?.resize());window.addEventListener('blur',clearInput);window.addEventListener('beforeunload',save);document.addEventListener('visibilitychange',()=>{clearInput();save();if(document.hidden)A.suspend();});
function frame(now){const dt=lastFrame?Math.min(C.maxFrame,(now-lastFrame)/C.milliseconds):0;lastFrame=now;if(scene==='game'&&G.state()){if(window.RPGOnline?.isActive()){window.RPGOnline.step(dt,!modalKind&&!document.hidden?movementInput():{x:0,y:0});}else if(!modalKind&&!document.hidden){const input=movementInput();G.setInput(input.x,input.y);let left=dt;while(left>0){const step=Math.min(C.step,left);G.tick(step);left-=step;}saveClock+=dt;if(saveClock>=C.saveInterval){saveClock=0;save();}}const sounds=[...new Set(G.state().sounds)];G.state().sounds=[];for(const id of sounds)A.play(id);hudClock+=dt;if(hudClock>=C.hudInterval){hudClock=0;updateHUD();}renderer?.render(dt);}A.update(scene==='game'&&G.state()?G.mapDef().music:'town');requestAnimationFrame(frame);}
try{const saved=JSON.parse(localStorage.getItem(C.storageKey)||'null');if(saved)G.load(saved);}catch{}
showTitle();requestAnimationFrame(frame);window.RPGUI={openModal,closeModal,refreshModal,openWorldInteraction,openInteraction,toast,changes,victory,showTitle,showCreation,showGame,openInventory,openTalents,openQuests,openMap,openNpc,openSettings,updateHUD,handleAction,frame,save,getRenderer:()=>renderer};window.RPGOnline?.init();
})();
